begin;
do $$
declare owner_id uuid; guest_id uuid; g uuid:=gen_random_uuid(); t uuid:=gen_random_uuid(); mo uuid:=gen_random_uuid(); mg uuid:=gen_random_uuid(); cid uuid; child uuid; state jsonb; payload jsonb; summary jsonb; view_data jsonb; revision bigint; member_count integer;
begin
 select id into owner_id from auth.users where email_confirmed_at is not null and not coalesce(is_anonymous,false) order by created_at limit 1;
 select id into guest_id from auth.users where email_confirmed_at is not null and not coalesce(is_anonymous,false) and id<>owner_id order by created_at limit 1;
 perform set_config('request.jwt.claim.sub',owner_id::text,true);
 insert into public.travel_groups(id,owner_id,name) values(g,owner_id,'Canonical companions rollback fixture');
 insert into public.trips(id,group_id,organizer_id,name,event_type) values(t,g,owner_id,'Canonical companions fixture','celebration');
 insert into public.trip_access(trip_id,profile_id,role,granted_by) values(t,owner_id,'organizer',owner_id),(t,guest_id,'participant',owner_id);
 insert into public.group_members(id,group_id,display_name,created_by,local_source_id) values(mo,g,'Organizador',owner_id,'member-owner'),(mg,g,'Convidada',owner_id,'member-guest');
 insert into public.trip_participants(trip_id,member_id,local_source_id) values(t,mo,'owner'),(t,mg,'guest');
 insert into public.member_profile_links(member_id,profile_id,status,authorized_by) values(mo,owner_id,'active',owner_id),(mg,guest_id,'active',owner_id);
 payload:=jsonb_build_object('trip',jsonb_build_object('id','local','groupId','local-group','eventType','event','name','Fixture','potluckMode','potluck','contributionPlan',jsonb_build_object('mode','cost_split','costSource','manual','goalCents',60000,'openingBalanceCents',0,'participantIds',jsonb_build_array('owner','guest'),'participantOrder',jsonb_build_array('owner','guest'),'monthCount',1,'months',jsonb_build_array('2026-12'))),'people',jsonb_build_array(jsonb_build_object('id','owner','memberId','member-owner','trip','local','name','Organizador','contributes',true),jsonb_build_object('id','guest','memberId','member-guest','trip','local','name','Convidada','contributes',true)),'members','[]'::jsonb,'payments',jsonb_build_array(jsonb_build_object('id','payment','amountCents',6000,'allocations',jsonb_build_array(jsonb_build_object('participantId','owner','amountCents',6000)),'referenceMonth','2026-12')));
 insert into public.trip_snapshots(trip_id,payload,revision,updated_by) values(t,payload,1,owner_id);
 perform set_config('request.jwt.claim.sub',guest_id::text,true);
 state:=public.change_event_companions(t,'save','{"name":"Mãe","kind":"adult","contributes":false}',0);
 select id into cid from public.event_companions where trip_id=t and responsible_id=guest_id;
 if not exists(select 1 from public.event_companions where id=cid and contributes and participant_id is not null and member_id is not null) then raise exception 'canonical identity or safe paying default missing';end if;
 summary:=public.get_trip_financial_summary(t);
 if (summary->>'confirmed_payer_count')::int<>3 or (summary->>'split_per_person_cents')::bigint<>20000 then raise exception 'paying companion missing in split %',summary;end if;
 begin perform public.change_event_companions(t,'save',jsonb_build_object('id',cid,'name','Mãe','kind','adult','contributes',false),1);raise exception 'self exemption accepted';exception when others then if sqlerrm<>'organizer sets contribution' then raise;end if;end;
 perform set_config('request.jwt.claim.sub',owner_id::text,true);
 state:=public.change_event_companions(t,'save','{"name":"Criança","kind":"child","contributes":false}',0);
 select id into child from public.event_companions where trip_id=t and responsible_id=owner_id;
 if (select count(*) from public.trip_participants where trip_id=t and removed_at is null)<>4 then raise exception 'total attendance must be four';end if;
 summary:=public.get_trip_financial_summary(t);
 if (summary->>'confirmed_payer_count')::int<>3 or (summary->>'split_per_person_cents')::bigint<>20000 then raise exception 'exempt child counted as payer';end if;
 perform set_config('request.jwt.claim.sub',guest_id::text,true);
 view_data:=public.get_participant_trip_view(t);
 if (view_data->>'participant_count')::int<>4 or jsonb_array_length(view_data->'shared_details'->'confirmed')<>4 then raise exception 'guest count mismatch';end if;
 if not exists(select 1 from jsonb_array_elements(view_data->'shared_details'->'confirmed') p where p->>'name'='Criança' and (p->>'contributes')::boolean=false and (p->>'is_companion')::boolean) then raise exception 'guest exemption label missing';end if;
 if exists(select 1 from public.member_profile_links mpl join public.event_companions ec on ec.member_id=mpl.member_id where ec.trip_id=t) then raise exception 'companions granted account identity';end if;
 perform set_config('request.jwt.claim.sub',owner_id::text,true);
 select s.payload,s.revision into payload,revision from public.trip_snapshots s where trip_id=t;
 payload:=jsonb_set(payload,'{people}',(select jsonb_agg(case when p->>'companionId'=cid::text then p||'{"contributes":false,"name":"Mãe editada"}'::jsonb else p end) from jsonb_array_elements(payload->'people') p));
 revision:=public.sync_trip_snapshot(t,payload,revision);
 if not exists(select 1 from public.event_companions where id=cid and not contributes and name='Mãe editada') then raise exception 'People changes not reflected in companion';end if;
 summary:=public.get_trip_financial_summary(t);
 if (summary->>'confirmed_payer_count')::int<>2 or (summary->>'split_per_person_cents')::bigint<>30000 then raise exception 'exemption not reflected in split';end if;
 select s.payload into payload from public.trip_snapshots s where trip_id=t;
 revision:=public.sync_trip_snapshot(t,payload,revision);
 if (select count(*) from public.trip_participants where trip_id=t)<>4 or (select count(*) from jsonb_array_elements((select s.payload->'people' from public.trip_snapshots s where trip_id=t)))<>4 then raise exception 'repeat sync duplicated participants';end if;
 if (select s.payload->'payments' from public.trip_snapshots s where trip_id=t)<>jsonb_build_array(jsonb_build_object('id','payment','amountCents',6000,'allocations',jsonb_build_array(jsonb_build_object('participantId','owner','amountCents',6000)),'referenceMonth','2026-12')) then raise exception 'payment allocation changed';end if;
 select ec.revision into revision from public.event_companions ec where ec.id=child;
 state:=public.change_event_companions(t,'remove',jsonb_build_object('id',child),revision);
 if (select count(*) from public.trip_participants where trip_id=t and removed_at is null)<>3 then raise exception 'removed companion still counted';end if;
 if not exists(select 1 from jsonb_array_elements((select s.payload->'people' from public.trip_snapshots s where trip_id=t)) p where p->>'companionId'=child::text and (p->>'removedFromTrip')::boolean) then raise exception 'historical identity lost';end if;
 if has_function_privilege('authenticated','public.refresh_companion_participants(uuid)','EXECUTE') or has_function_privilege('authenticated','public.reflect_companion_participant()','EXECUTE') then raise exception 'internal bypass exposed';end if;
end $$;
rollback;
